[HttpGet("{id:guid}")]
public async Task<ActionResult<OrderDto>> GetById(Guid id, IOrderService svc, CancellationToken ct)
{
    var order = await svc.FindAsync(id, ct);
    if (order is null) return NotFound();
    return order; // implicit Ok(order) — compiler knows success type is OrderDto
}

[HttpPost]
public async Task<ActionResult<OrderDto>> Create(CreateOrderRequest req, IOrderService svc, CancellationToken ct)
{
    var created = await svc.CreateAsync(req, ct);
    return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
}

[HttpDelete("{id:guid}")]
public async Task<IActionResult> Delete(Guid id, IOrderService svc, CancellationToken ct)
{
    var deleted = await svc.DeleteAsync(id, ct);
    return deleted ? NoContent() : NotFound();
}

app.MapGet("/api/orders/{id:guid}", async Task<Results<Ok<OrderDto>, NotFound>> (
    Guid id, IOrderService svc, CancellationToken ct) =>
{
    var order = await svc.FindAsync(id, ct);
    return order is null ? TypedResults.NotFound() : TypedResults.Ok(order);
});

